import{_ as s,H as e,f as n,i as t}from"./chunks/framework.DIv0Dgmf.js";const u=JSON.parse('{"title":"第五章：读懂代码库","description":"学会让 Claude 分析和理解现有代码","frontmatter":{"title":"第五章：读懂代码库","description":"学会让 Claude 分析和理解现有代码"},"headers":[],"relativePath":"guide/2-basic-usage/5-understand-codebase.md","filePath":"guide/2-basic-usage/5-understand-codebase.md"}'),i={name:"guide/2-basic-usage/5-understand-codebase.md"};function l(p,a,d,o,c,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="第五章-读懂代码库" tabindex="-1">第五章：读懂代码库 <a class="header-anchor" href="#第五章-读懂代码库" aria-label="Permalink to &quot;第五章：读懂代码库&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你分析和理解现有代码，掌握大项目分析策略。</p></div><h2 id="为什么让-ai-读代码更快" tabindex="-1">为什么让 AI 读代码更快？ <a class="header-anchor" href="#为什么让-ai-读代码更快" aria-label="Permalink to &quot;为什么让 AI 读代码更快？&quot;">​</a></h2><p>想象你要接手一个陌生人的项目：</p><ul><li>自己读：可能需要几天</li><li>让 Claude 读：几分钟就能了解大概</li></ul><p>Claude 可以快速理解代码结构，帮你回答&quot;这个项目是做什么的&quot;、&quot;某个函数在哪里&quot;等问题。</p><h2 id="小项目分析" tabindex="-1">小项目分析 <a class="header-anchor" href="#小项目分析" aria-label="Permalink to &quot;小项目分析&quot;">​</a></h2><h3 id="基本流程" tabindex="-1">基本流程 <a class="header-anchor" href="#基本流程" aria-label="Permalink to &quot;基本流程&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 你的项目路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>然后直接问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请分析一下这个项目的结构</span></span></code></pre></div><p>Claude 会读取目录下的文件，告诉你项目的基本情况。</p><h2 id="大项目分析策略" tabindex="-1">大项目分析策略 <a class="header-anchor" href="#大项目分析策略" aria-label="Permalink to &quot;大项目分析策略&quot;">​</a></h2><p>当项目有数十甚至数百个文件时，一次性分析会：</p><ul><li>消耗大量 Token</li><li>产生过多无关信息</li><li>分析速度很慢</li></ul><p><strong>正确策略：分层探索</strong></p><h3 id="第一步-找入口点" tabindex="-1">第一步：找入口点 <a class="header-anchor" href="#第一步-找入口点" aria-label="Permalink to &quot;第一步：找入口点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个项目的入口文件是哪个？</span></span></code></pre></div><p>入口文件通常是：</p><ul><li><code>main.py</code> / <code>main.js</code> / <code>main.ts</code></li><li><code>app.py</code> / <code>app.js</code> / <code>App.tsx</code></li><li><code>index.js</code> / <code>index.ts</code></li></ul><h3 id="第二步-理解模块划分" tabindex="-1">第二步：理解模块划分 <a class="header-anchor" href="#第二步-理解模块划分" aria-label="Permalink to &quot;第二步：理解模块划分&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个项目有哪些主要模块？</span></span></code></pre></div><h3 id="第三步-逐个深入" tabindex="-1">第三步：逐个深入 <a class="header-anchor" href="#第三步-逐个深入" aria-label="Permalink to &quot;第三步：逐个深入&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先看看 auth 相关模块是怎么实现的</span></span></code></pre></div><h3 id="第四步-追踪调用链" tabindex="-1">第四步：追踪调用链 <a class="header-anchor" href="#第四步-追踪调用链" aria-label="Permalink to &quot;第四步：追踪调用链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个函数在哪里被调用了？</span></span></code></pre></div><h2 id="问更具体的问题" tabindex="-1">问更具体的问题 <a class="header-anchor" href="#问更具体的问题" aria-label="Permalink to &quot;问更具体的问题&quot;">​</a></h2><h3 id="问单个文件" tabindex="-1">问单个文件 <a class="header-anchor" href="#问单个文件" aria-label="Permalink to &quot;问单个文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个 main.py 的主要功能是什么？</span></span></code></pre></div><h3 id="问某个函数" tabindex="-1">问某个函数 <a class="header-anchor" href="#问某个函数" aria-label="Permalink to &quot;问某个函数&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我理解 utils.py 里的 helper 函数</span></span></code></pre></div><h3 id="问整体架构" tabindex="-1">问整体架构 <a class="header-anchor" href="#问整体架构" aria-label="Permalink to &quot;问整体架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个项目是怎么组织的？有哪些主要模块？</span></span></code></pre></div><h3 id="问依赖关系" tabindex="-1">问依赖关系 <a class="header-anchor" href="#问依赖关系" aria-label="Permalink to &quot;问依赖关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个模块依赖哪些其他模块？</span></span></code></pre></div><h3 id="问调用链路" tabindex="-1">问调用链路 <a class="header-anchor" href="#问调用链路" aria-label="Permalink to &quot;问调用链路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从入口到这个函数，调用链是怎样的？</span></span></code></pre></div><h2 id="上下文管理" tabindex="-1">上下文管理 <a class="header-anchor" href="#上下文管理" aria-label="Permalink to &quot;上下文管理&quot;">​</a></h2><h3 id="短对话-vs-长对话" tabindex="-1">短对话 vs 长对话 <a class="header-anchor" href="#短对话-vs-长对话" aria-label="Permalink to &quot;短对话 vs 长对话&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>探索性分析</td><td>短对话，问完就结束</td></tr><tr><td>深入理解</td><td>长对话，保持上下文</td></tr><tr><td>超过 50 条消息</td><td>开新对话</td></tr></tbody></table><h3 id="开新对话的时机" tabindex="-1">开新对话的时机 <a class="header-anchor" href="#开新对话的时机" aria-label="Permalink to &quot;开新对话的时机&quot;">​</a></h3><ul><li>对话超过 50 条消息</li><li>换了完全不相关的任务</li><li>想重新分析</li></ul><h3 id="交接上下文" tabindex="-1">交接上下文 <a class="header-anchor" href="#交接上下文" aria-label="Permalink to &quot;交接上下文&quot;">​</a></h3><p>换对话时，简要描述背景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在分析一个 Flask 博客项目，已经知道：</span></span>
<span class="line"><span>1. 使用 JWT 认证</span></span>
<span class="line"><span>2. 文章存在 PostgreSQL</span></span>
<span class="line"><span>3. 有用户和评论模块</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现在要了解评论功能实现...</span></span></code></pre></div><h2 id="实际案例" tabindex="-1">实际案例 <a class="header-anchor" href="#实际案例" aria-label="Permalink to &quot;实际案例&quot;">​</a></h2><h3 id="场景-接手一个博客项目" tabindex="-1">场景：接手一个博客项目 <a class="header-anchor" href="#场景-接手一个博客项目" aria-label="Permalink to &quot;场景：接手一个博客项目&quot;">​</a></h3><p><strong>第一轮：快速了解</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：这个项目是做什么的？</span></span>
<span class="line"><span>Claude：这是一个博客系统，使用 Python Flask 框架...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你：入口文件在哪里？</span></span>
<span class="line"><span>Claude：入口文件是 app.py...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你：有哪些主要模块？</span></span>
<span class="line"><span>Claude：auth（认证）、post（文章）、comment（评论）...</span></span></code></pre></div><p><strong>第二轮：深入某个模块</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：用户认证是怎么实现的？</span></span>
<span class="line"><span>Claude：在 auth.py 文件里，使用 JWT token...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你：JWT 密钥在哪里配置？</span></span>
<span class="line"><span>Claude：在 config.py 的 SECRET_KEY...</span></span></code></pre></div><h3 id="场景-理解调用链路" tabindex="-1">场景：理解调用链路 <a class="header-anchor" href="#场景-理解调用链路" aria-label="Permalink to &quot;场景：理解调用链路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：追踪一下用户发表评论的完整流程</span></span>
<span class="line"><span>Claude：</span></span>
<span class="line"><span>1. 用户提交评论 → routes/comment.py:create()</span></span>
<span class="line"><span>2. 验证权限 → middleware/auth.py:require_login()</span></span>
<span class="line"><span>3. 保存到数据库 → models/comment.py:Comment.create()</span></span>
<span class="line"><span>4. 发送通知 → services/notification.py:send_email()</span></span></code></pre></div><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>知道什么是代码文件（.py, .js 等）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 读错了？</strong></p><p>A: 确认你在正确的目录下，用 <code>pwd</code> 查看当前位置。</p><p><strong>Q: 大项目分析很慢？</strong></p><p>A: 先指定具体文件，不要一次性分析整个项目。按入口→模块→细节的顺序探索。</p><p><strong>Q: 对话太长了怎么办？</strong></p><p>A: 输入 <code>/clear</code> 清空对话，或开新对话并简要描述背景。</p><p><strong>Q: Claude 忘了之前说的？</strong></p><p>A: 可以在对话开始时说&quot;/memory&quot;查看记忆，或重新描述上下文。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>找一个有 10+ 文件的项目，用分层策略分析</li><li>练习追踪一个函数的调用链</li><li>测试开新对话时的上下文交接</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何让 Claude 帮你编辑和创建代码。</p><p><a href="/claude-code-guide/guide/2-basic-usage/6-edit-code.html">👉 第六章：编辑和创建代码</a></p>`,69)])])}const b=s(i,[["render",l]]);export{u as __pageData,b as default};
